  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    edges = []
    for u, v, d in distances:
        mutual = max(core[u], core[v], d)
        if u < v:
            edges.append((mutual, u, v))
        else:
            edges.append((mutual, v, u))
    edges.sort()  # sort by mutual, then u, then v
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            if xr < yr:
                parent[yr] = xr
                rank[xr] += 1
            else:
                parent[xr] = yr
                rank[yr] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Disconnected graph')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
